  // belong in KPI / assurance views, not in this actionable queue.
  for(const person of state.staff||[]){
   const hrs=bookings.filter(b=>b.staffId===person.id).reduce((n,b)=>n+Number(b.durationHours||0),0);
   if(hrs<=20)continue;
   const proposal={id:`IMP-SW-${person.id}`,sourceStaffId:person.id,type:'Staffing',severity:'Medium',title:`Load-balancing opportunity · ${person.name}`,why:`${hrs.toFixed(1)} booked hours are concentrated on this person.`,owner:'Prototype Lab Planner',impact:'Reduces bottleneck risk without adding headcount.',action:'Apply staff rebalance'};
   const plan=this._staffBalancePlan(state,proposal);
   if(plan.resolved&&plan.changes.length){proposal.prevalidated=true;proposal.prevalidatedAt=P.now();proposal.proposal=`Move ${plan.changes.length} booking${plan.changes.length===1?'':'s'} (${plan.movedHours.toFixed(1)} h) to conflict-free, qualified staff.`;proposal.previewChanges=plan.changes;proposal.expectedRemainingHours=plan.remainingHours;out.push(proposal);}
  }
  for(const eq of state.equipment||[]){
   const hrs=bookings.filter(b=>b.equipmentId===eq.id).reduce((n,b)=>n+Number(b.durationHours||0),0);
   if(hrs<=18)continue;
   const proposal={id:`IMP-EQ-${eq.id}`,equipmentId:eq.id,type:'Capacity',severity:'Medium',title:`Equipment load-balancing opportunity · ${eq.name}`,why:`${hrs.toFixed(1)} booked hours are concentrated on this asset.`,owner:'Lab Manager',impact:'Reduces bottleneck risk using existing qualified capacity.',action:'Apply equipment rebalance'};
   const plan=this._equipmentBalancePlan(state,proposal);
   if(plan.resolved&&plan.changes.length){proposal.prevalidated=true;proposal.prevalidatedAt=P.now();proposal.proposal=`Move ${plan.changes.length} booking${plan.changes.length===1?'':'s'} (${plan.movedHours.toFixed(1)} h) to conflict-free, ready equivalent equipment.`;proposal.previewChanges=plan.changes;proposal.expectedRemainingHours=plan.remainingHours;out.push(proposal);}
  }
  const latest=new Map();for(const d of (state.improvementDecisions||[]).slice().sort((a,b)=>String(a.at||'').localeCompare(String(b.at||''))))latest.set(d.proposalId,d);const today=P.todayISO();
